{
  "contract": "SafePaymentVault",
  "closure": {
    "site_function": "Withdraw",
    "site_call": ".call",
    "functions": [
      "Withdraw",
      "GetTotalBalance",
      "MakeDeposit"
    ],
    "justification": "GetTotalBalance and MakeDeposit affect TotalBalance and _ethBal, which are exposed during Withdraw."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "GetTotalBalance",
      "MakeDeposit"
    ],
    "nesting_bound": {
      "Withdraw": 0,
      "GetTotalBalance": 1,
      "MakeDeposit": 1
    }
  },
  "phases": {
    "function": "Withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "Withdraw:ENTRY",
      "to_marker": "Withdraw:CALL:BEFORE"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "Withdraw:CALL:BEFORE",
      "to_marker": "Withdraw:CALL:AFTER"
    },
    "post": {
      "name": "post",
      "from_marker": "Withdraw:CALL:AFTER",
      "to_marker": "Withdraw:EXIT"
    },
    "linearization_point": "Withdraw:CALL:AFTER"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "assets in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_ethBal == TotalBalance + inFlight",
    "stable_formula": "_ethBal == TotalBalance",
    "kind": "additive"
  },
  "composition": {
    "target_property": "TotalBalance == _ethBal",
    "rule": "During the exposed phase, the invariant _ethBal == TotalBalance + inFlight ensures consistency of balance states amidst callbacks."
  }
}
